// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Prepare: everything the model step needs is decided here, in code.
// The customer's text is data. It is wrapped and never mixed into the instructions.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
let message = String(body.message ?? '');
if (cfg.normalise_digits) message = westernDigits(message);
const glossary = Object.entries(cfg.glossary || {}).map(([term, meaning]) => `- ${term}: ${meaning}`);
// The instructions name the business and, where the model must pick from a list, carry that list.
// Found on the first run with a real model (21 November 2026): the placeholder reached the model as written,
// and the booking instructions said "the approved list" without giving it.
const services = Array.isArray(cfg.services) ? cfg.services.map((name) => `- ${name}`) : [];
const system = String(cfg.instructions).split('(اسم المنشأة)').join(cfg.business_name || 'المنشأة')
  + (services.length ? '\n\nالقائمة المعتمدة للخدمات (اكتب الاسم كما هو هنا):\n' + services.join('\n') : '')
  + (glossary.length ? '\n\nمصطلحات العملاء:\n' + glossary.join('\n') : '');
const stopped = Boolean(cfg.stopped);
return [{
  json: {
    message,
    account: String(body.account ?? ''),
    ref: String(body.ref ?? ''), // the caller's own id for this message; used by the shadow record
    state: body.state && typeof body.state === 'object' ? body.state : {},
    stopped,
    route: !stopped && cfg.model_mode === 'http' ? 'http' : 'sim',
    model_url: String(cfg.model_base_url || '').replace(/\/+$/, '') + '/chat/completions',
    request_body: {
      model: cfg.model_name,
      temperature: 0,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `<customer_message>\n${message}\n</customer_message>` },
      ],
    },
  },
}];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Simulated extraction: NOT a language model. It reads labelled lines ("رقم الفاتورة: ...")
// from the invoice text, so the workflow runs with no key and no cost. A real model reads
// unlabelled and scanned invoices; the checks in Decide are the same either way.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const text = westernDigits($input.first().json.message);
const LABELS = {
  supplier: ['المورد', 'المورّد', 'supplier'], vat_number: ['الرقم الضريبي', 'vat number'], invoice_number: ['رقم الفاتورة', 'invoice number', 'invoice no'],
  date: ['التاريخ', 'date'], net: ['المبلغ قبل الضريبة', 'net'], vat: ['مبلغ الضريبة', 'vat amount'], total: ['الإجمالي', 'الاجمالي', 'total'], currency: ['العملة', 'currency'],
};
const fields = {};
for (const line of text.split('\n')) {
  const at = line.indexOf(':');
  if (at < 0) continue;
  const label = normalise(line.slice(0, at)).trim();
  const field = Object.keys(LABELS).find((f) => LABELS[f].some((l) => normalise(l) === label));
  if (field && !(field in fields)) fields[field] = line.slice(at + 1).trim();
}
return [{ json: { understanding: { fields } } }];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Decide: template 4, invoice reconciliation. The model only extracts fields. Arithmetic,
// duplicates, supplier matching and bank matching are rules, in code. Entries are drafts:
// nothing is posted until the accountant approves, and there is no tool to pay or to file.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
// The model's answer is untrusted: take one JSON object out of it, or nothing.
function readModel(item) {
  if (item && item.understanding && typeof item.understanding === 'object') return item.understanding;
  try {
    const content = item.choices[0].message.content;
    const parsed = JSON.parse(content.slice(content.indexOf('{'), content.lastIndexOf('}') + 1));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    return { error: 'model_output_unreadable' }; // a model failure must never act on its own
  }
}
const cfg = $('Config').first().json;
const prepared = $('Prepare').first().json;
const understood = readModel($input.first().json);
// One result shape for every template. `level` is the row of the oversight table that applied.
const result = { action: null, level: null, intent: 'unknown', reply_draft: '', handover: null, pending_approval: [],
  notify_staff: [], tool_calls: [], state: {}, log: { account: maskPhone(prepared.account) } };
// Shadow mode (Config `shadow_mode`: true): the agent runs beside the staff and nothing leaves it.
// Decide works on a copy of the workflow's stored data, so no booking or draft is kept, and `done`
// moves everything the agent would have sent, written or asked for under `shadow.would`.
// Reads still happen: the agent cannot say what it would do without looking, so the customer's
// data is processed all the same. The caller files the shadow record; `ref` ties it to the staff's record.
const shadowMode = cfg.shadow_mode === true;
const storedData = () => (shadowMode ? JSON.parse(JSON.stringify($getWorkflowStaticData('global'))) : $getWorkflowStaticData('global'));
const done = (fields) => {
  Object.assign(result, fields);
  if (!shadowMode) return [{ json: result }];
  const { intent, log, ...would } = result;
  return [{ json: { mode: 'shadow', action: 'shadow_observed', level: 'shadow', intent, reply_draft: '', handover: null,
    pending_approval: [], notify_staff: [], tool_calls: [], state: prepared.state, log: Object.assign(log, { shadow: true }),
    shadow: { ref: prepared.ref, would } } }];
};
const handover = (action, level, summary, reply, urgency = 'normal') => done({ action, level,
  handover: { summary, urgency }, reply_draft: reply || 'شكراً لتواصلك. حوّلنا طلبك إلى أحد الفريق وسيتواصل معك.' });
const own = (object, key) => (typeof key === 'string' && Object.prototype.hasOwnProperty.call(object, key) ? object[key] : null);
result.intent = 'reconcile';
const store = storedData(); // a discarded copy in shadow mode
store.seen = store.seen || [];
store.drafts = store.drafts || {};

if (prepared.stopped) return handover('stopped', 'stopped', 'سير العمل موقوف. الفواتير تُراجع يدوياً.', '');

const raw = understood.fields && typeof understood.fields === 'object' ? understood.fields : {};
const REQUIRED = ['supplier', 'vat_number', 'invoice_number', 'date', 'net', 'vat', 'total', 'currency'];
const text = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v).trim() : '');
const amount = (v) => { const s = westernDigits(text(v)).replace(/[,\s]/g, ''); return /^\d+(\.\d{1,2})?$/.test(s) ? Math.round(Number(s) * 100) : null; }; // halalas, exact
const fields = Object.fromEntries(REQUIRED.map((f) => [f, text(raw[f])]));
const [net, vat, total] = ['net', 'vat', 'total'].map((f) => amount(raw[f]));
const exceptions = [];
const flag = (code, reason, action) => exceptions.push({ code, reason, suggested_action: action });

const missing = REQUIRED.filter((f) => !fields[f] || (['net', 'vat', 'total'].includes(f) && amount(raw[f]) === null));
if (missing.length) flag('missing_field', `حقول ناقصة أو غير مقروءة: ${missing.join('، ')}`, 'اطلب نسخة أوضح من الفاتورة أو أدخل الحقول يدوياً.');
if (fields.date && !/^\d{4}-\d{2}-\d{2}$/.test(fields.date)) flag('date_format', 'التاريخ ليس بصيغة YYYY-MM-DD. لم يُحوَّل.', 'راجع التاريخ في المستند، وحوّل الهجري بأداة لا بالنموذج.');
if (net !== null && vat !== null && total !== null) {
  if (net + vat !== total) flag('amount_mismatch', 'الصافي مع الضريبة لا يساوي الإجمالي.', 'راجع الفاتورة مع المورّد.');
  if (Math.abs(Math.round(net * cfg.vat_rate_set_by_accountant) - vat) > cfg.tolerance_halalas) flag('vat_inconsistency', 'مبلغ الضريبة لا يطابق النسبة التي حددها المحاسب.', 'المحاسب يقرر المعاملة الضريبية.');
}
// Supplier: matched across Arabic and English spellings from the supplier list. No guess.
const supplier = cfg.suppliers.find((s) => [s.name, ...s.variants].some((n) => normalise(n) === normalise(fields.supplier)));
if (fields.supplier && !supplier) flag('unknown_supplier', 'المورّد ليس في قائمة المورّدين بأي من تهجئاته.', 'أضف التهجئة إلى القائمة بعد التحقق، أو راجع الفاتورة.');
if (supplier && fields.vat_number && supplier.vat_number !== fields.vat_number) flag('vat_number_mismatch', 'الرقم الضريبي لا يطابق المسجّل للمورّد.', 'تحقق من المورّد قبل أي قيد.');
const key = `${supplier ? supplier.id : normalise(fields.supplier)}|${fields.invoice_number}`;
const duplicate = Boolean(fields.invoice_number) && (cfg.posted_invoices.includes(key) || store.seen.includes(key));
if (duplicate) flag('duplicate', 'فاتورة بالرقم نفسه للمورّد نفسه سبق تسجيلها.', 'لا تُقيَّد مرتين.');
// Bank line: same amount, and the invoice number in the reference.
const line = total === null ? null : cfg.bank_lines.find((b) => Math.round(b.amount * 100) === total && fields.invoice_number && b.reference.includes(fields.invoice_number));
if (!line && total !== null && !duplicate) flag('no_bank_match', 'لا حركة بنكية بالمبلغ نفسه ورقم الفاتورة.', 'قد تكون غير مدفوعة بعد، أو دُفعت بمرجع آخر.');

const report = { fields, matched_bank_line: line ? line.id : null, exceptions };
if (exceptions.length) {
  return done({ action: 'exception_report', level: 'autonomous', report, handover: { summary: `فاتورة فيها ${exceptions.length} استثناء. للمراجعة.`, urgency: 'normal' } });
}
store.seen.push(key);
const draftId = 'D-' + String(Object.keys(store.drafts).length + 1).padStart(3, '0');
store.drafts[draftId] = { key, supplier: supplier.id, invoice_number: fields.invoice_number, total: total / 100, bank_line: line.id, status: 'draft' };
result.tool_calls.push({ tool: 'ledger_write_draft', input: draftId });
result.pending_approval.push({ action: 'post_entry', draft: draftId, level: 'approve', approver: 'accountant' });
return done({ action: 'draft_entry', level: 'autonomous', report, draft: Object.assign({ id: draftId }, store.drafts[draftId]) });

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// The accountant posts a draft. Nothing is posted without a name, and a draft is posted once.
const body = $input.first().json.body || {};
const store = $getWorkflowStaticData('global');
const draftId = String(body.draft ?? '');
const approvedBy = String(body.approved_by ?? '').trim();
const draft = store.drafts && Object.prototype.hasOwnProperty.call(store.drafts, draftId) ? store.drafts[draftId] : null;
if (!approvedBy) return [{ json: { ok: false, error: 'posting needs a named accountant' } }];
if (!draft) return [{ json: { ok: false, error: 'unknown draft' } }];
if (draft.status !== 'posted') Object.assign(draft, { status: 'posted', approved_by: approvedBy });
return [{ json: Object.assign({ ok: true, id: draftId }, draft) }];
